<!doctype html><html lang="<?= fcc_language_tag() ?>"><head><?php fcc_i18n_assets(); ?><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?= $h(fcc_webinar_title($s)) ?> <?= htmlspecialchars(fcc_t('· FCC'), ENT_QUOTES, 'UTF-8') ?></title><link rel="stylesheet" href="<?= ASSETS_FULL_URL ?>css/fcc-webinar.css?v=<?= filemtime(ASSETS_PATH.'css/fcc-webinar.css') ?>"></head><body class="fv-public"><main class="fv-public-shell"><header class="fv-public-brand"><strong><?= htmlspecialchars(fcc_t('Forever Card Club'), ENT_QUOTES, 'UTF-8') ?></strong><span><?= htmlspecialchars(fcc_t('Osobni poziv'), ENT_QUOTES, 'UTF-8') ?></span></header><section class="fv-guest-card fv-single-card"><span class="fv-eyebrow"><?= $h(fcc_event_types()[$d['kind']]) ?></span><h1><?= $h(fcc_webinar_title($s)) ?></h1><p><?= nl2br($h($d['description'])) ?></p><div class="fv-guest-date"><strong><?= $h(fcc_event_label($s)) ?></strong></div><?php if($s['status']==='cancelled'): ?><p><?= htmlspecialchars(fcc_t('Ovaj termin je otkazan.'), ENT_QUOTES, 'UTF-8') ?></p><?php elseif($s['status']==='postponed'): ?><p><?= htmlspecialchars(fcc_t('Novi datum još nije potvrđen.'), ENT_QUOTES, 'UTF-8') ?></p><?php elseif($s['ends_at_utc']<=gmdate('Y-m-d H:i:s')): ?><p><?= htmlspecialchars(fcc_t('Ovaj je događaj završio. Za novi poziv javi se osobi koja te pozvala.'), ENT_QUOTES, 'UTF-8') ?></p><?php elseif(fcc_event_joinable($s)): ?><a class="fv-button" href="<?= $h(url('webinar-event/'.$s['id'].'?'.http_build_query(['ref'=>$ref,'join'=>1]))) ?>"><?= htmlspecialchars(fcc_t('Otvori webinar'), ENT_QUOTES, 'UTF-8') ?></a><?php elseif($d['mode']==='in_person'): ?><p><?= htmlspecialchars(fcc_t('Mjesto:'), ENT_QUOTES, 'UTF-8') ?> <?= $h($d['location']) ?></p><?php else: ?><p><?= htmlspecialchars(fcc_t('Pristup se otvara'), ENT_QUOTES, 'UTF-8') ?> <?= (int)$d['join_minutes'] ?> <?= htmlspecialchars(fcc_t('minuta prije početka.'), ENT_QUOTES, 'UTF-8') ?></p><?php endif ?><?php if(!empty($d['previous_start'])): ?><p><?= htmlspecialchars(fcc_t('Termin je promijenjen. Ovdje je aktualni raspored.'), ENT_QUOTES, 'UTF-8') ?></p><?php endif ?><?php if(!empty($d['change_reason'])): ?><p><?= $h($d['change_reason']) ?></p><?php endif ?></section><footer class="fv-public-footer"><p><?= htmlspecialchars(fcc_t('FCC je neovisan sustav našeg tima.'), ENT_QUOTES, 'UTF-8') ?></p><a href="<?= $h(fcc_legal_url('privacy')) ?>"><?= htmlspecialchars(fcc_t('Politika privatnosti'), ENT_QUOTES, 'UTF-8') ?></a> · <a href="<?= $h(fcc_legal_url('terms')) ?>"><?= htmlspecialchars(fcc_t('Uvjeti korištenja'), ENT_QUOTES, 'UTF-8') ?></a></footer></main></body></html>
